// Side of the largest square of 1s with (i, j) as its top-left corner
int solve(int i, int j, vector<vector<int>> &mat,
          vector<vector<int>> &dp, int &maxSide) {
    int n = mat.size(), m = mat[0].size();

    // Base case: cell is outside the matrix
    if (i >= n || j >= m)
        return 0;

