    if (dp[i][j] != -1)
        return dp[i][j];

    // Explore right, bottom and diagonal cells first, so no cell is skipped
    int right = solve(i, j + 1, mat, dp, maxSide);
    int down = solve(i + 1, j, mat, dp, maxSide);
    int diag = solve(i + 1, j + 1, mat, dp, maxSide);

    // A cell with 0 cannot be part of any square
    if (mat[i][j] == 0)
        return dp[i][j] = 0;

    // Side at this cell is 1 + the smallest side among the three neighbours
    dp[i][j] = 1 + min({right, down, diag});

    // Update the maximum side found so far
    maxSide = max(maxSide, dp[i][j]);

    return dp[i][j];
}

