    #include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int maxSquare(vector<vector<int>> &mat) {
    int n = mat.size(), m = mat[0].size();

    // dp[i][j] = side of the largest square of 1s with (i, j) as its top-left corner
    // The extra last row and column stay 0, so no boundary checks are needed
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    int maxSide = 0;

    // Fill the table from the bottom-right to the top-left
    for (int i = n - 1; i >= 0; i--) {
        for (int j = m - 1; j >= 0; j--) {

            // A cell with 1 extends the smallest square among right, bottom and diagonal
            if (mat[i][j] == 1) {
                dp[i][j] = 1 + min({dp[i][j + 1], dp[i + 1][j], dp[i + 1][j + 1]});

                // Update the maximum side found so far
                maxSide = max(maxSide, dp[i][j]);
            }
        }
    }

    return maxSide;
}

