int maxSquare(vector<vector<int>> &mat) {
    int n = mat.size(), m = mat[0].size();

    // dp[i] = side of the largest square with (i, j) as its top-left corner
    // It holds the next column's values until they are overwritten by the current column
    // The extra last entry stays 0, so no boundary checks are needed
    vector<int> dp(n + 1, 0);
    int maxSide = 0;

    // Process the columns from right to left
    for (int j = m - 1; j >= 0; j--) {

        // Diagonal cell (i + 1, j + 1) of the next column, starts as 0 for the extra row
        int diag = 0;

        // Process the rows from bottom to top
        for (int i = n - 1; i >= 0; i--) {

            // Right cell (i, j + 1) is still stored in dp[i], save it before overwriting
            int right = dp[i];

            if (mat[i][j] == 1) {

                // Extend the smallest square among right, bottom and diagonal
                dp[i] = 1 + min({right, dp[i + 1], diag});

                // Update the maximum side found so far
                maxSide = max(maxSide, dp[i]);
            }
            else {

